    "52858a2e2daa57c74f5cff3193e81bf6e1132fd547c6dae8a11cb7c7754e36d4";

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) enum Shape {
    HorizontalEllipse,
    VerticalEllipse,
    PipeArch,
    Arch,
}

/// One evidence barrel: span and rise bits, then the given radii bits in constructor order.
#[derive(Clone, Copy, Debug)]
pub(super) struct Barrel {
    pub(super) name: &'static str,
    pub(super) shape: Shape,
    pub(super) inputs: &'static [u64],
}

/// True certificate values of one barrel.
#[derive(Clone, Copy, Debug)]
pub(super) struct Certified {
    pub(super) barrel: Barrel,
    /// Minimum of `d r_c / ds` over `[2^-30, 1 - 2^-53]`.
    pub(super) critical_minimum: u64,
    /// Conveyance peak `s_K`.
    pub(super) peak: [u64; 2],
    /// `ln k_max = (5 ln a - 2 ln p) / 3` at `s_K` in unit geometry.
    pub(super) log_peak: [u64; 2],
    /// `(s_j, minimum of d r_n / ds over [2^-30, s_j])`, `s_j` rising to `s_K`.
    pub(super) rising: &'static [(u64, u64)],
}

